.d .finc .fint{font-weight:600;color:var(--ml-ink)}
.d .fin .okc path{stroke-dasharray:1;stroke-dashoffset:1}
.d .app.paid .fin .okc path{animation:cm-draw 650ms var(--ml-ease) 250ms forwards}
